#!/usr/bin/env python3
"""Lossless, self-contained standard-library compressor."""
import bz2
import sys


def compress(data):
    return b'BC1' + bz2.compress(data, compresslevel=9)


def decompress(data):
    if not data.startswith(b'BC1'):
        raise ValueError('Invalid compressed file')
    return bz2.decompress(data[3:])


def main():
    args = sys.argv[1:]
    decode = bool(args and args[0] == '--decompress')
    if decode:
        args = args[1:]
    if len(args) != 2:
        raise SystemExit('usage: compress.py [--decompress] input output')
    with open(args[0], 'rb') as f:
        data = f.read()
    result = decompress(data) if decode else compress(data)
    with open(args[1], 'wb') as f:
        f.write(result)


if __name__ == '__main__':
    main()

