    n,width=len(rows),len(rows[0][1]);mod=max(int(r[3]) for r in rows)+1;step=int(rows[1][3]);texts=[r[2] for r in rows]
    ts=[collections.Counter(texts[j::6]).most_common(1)[0][0] for j in range(6)]
    flags=bytes(t!=ts[i%6] for i,t in enumerate(texts));ex=[t.split(b' ') for t,f in zip(texts,flags) if f];words=sorted(set(w for line in ex for w in line));ids={w:i for i,w in enumerate(words)}
    header=json.dumps([n,width,step,mod,[t.decode('latin1') for t in ts],[w.decode('latin1') for w in words]],separators=(',',':')).encode()
    return b'S'+bz2.compress(header+b'\n'+flags+bytes(map(len,ex))+bytes(ids[w] for line in ex for w in line))

def decompress(data):
    header,body=bz2.decompress(data[1:]).split(b'\n',1)
    n,width,step,mod,ts,words=json.loads(header);ts=[t.encode('latin1') for t in ts];words=[w.encode('latin1') for w in words]
    flags=body[:n];count=sum(flags);lengths=iter(body[n:n+count]);tokens=iter(body[n+count:])
    texts=[b' '.join(words[next(tokens)] for _ in range(next(lengths))) if f else ts[i%len(ts)] for i,f in enumerate(flags)]
    return b''.join(str(i).zfill(width).encode()+b' '+t+b' '+str(i*step%mod).encode()+b'\n' for i,t in enumerate(texts))

